components.css:
.ds-btn-primary { display: inline-flex; align-items: center; gap: 12px; padding: 16px 24px; border-radius: 8px; background: #111111; color: #F5F1E8; font-family: 'Inter', -apple-system, sans-serif; font-weight: 500; font-size: 14px; letter-spacing: 0.02em; border: 1px solid #111111; text-decoration: none; transition: transform 240ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-btn-primary:hover { transform: translateX(2px); }
.ds-btn-primary__arrow { transition: transform 240ms cubic-bezier(0.22, 0.61, 0.36, 1); display: inline-block; }
.ds-btn-primary:hover .ds-btn-primary__arrow { transform: translateX(4px); }
.ds-btn-primary:focus-visible { outline: 2px solid #D8A24A; outline-offset: 3px; }

.ds-btn-ghost { display: inline-flex; align-items: center; gap: 8px; padding: 12px 20px; border-radius: 8px; background: #F5F1E8; color: #111111; font-family: 'Inter', -apple-system, sans-serif; font-weight: 500; font-size: 13px; border: 1px solid #111111; text-decoration: none; transition: background 240ms cubic-bezier(0.22, 0.61, 0.36, 1), color 240ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-btn-ghost:hover { background: #111111; color: #F5F1E8; }
.ds-btn-ghost:focus-visible { outline: 2px solid #D8A24A; outline-offset: 3px; }

.ds-chip { text-align: left; padding: 24px; border-radius: 8px; border: 1px solid rgba(17,17,17,0.12); background: #EFE9DC; display: flex; flex-direction: column; gap: 6px; cursor: pointer; transition: background 240ms cubic-bezier(0.22, 0.61, 0.36, 1), border-color 240ms cubic-bezier(0.22, 0.61, 0.36, 1), color 240ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-chip:hover { border-color: rgba(17,17,17,0.22); }
.ds-chip:focus-visible { outline: 2px solid #D8A24A; outline-offset: 3px; }
.ds-chip__label { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 500; font-size: 18px; letter-spacing: -0.005em; color: #111111; }
.ds-chip__hint { font-family: 'Inter', -apple-system, sans-serif; font-size: 12px; line-height: 18px; color: #A79F93; }
.ds-chip--on { background: #111111; border-color: #111111; }
.ds-chip--on .ds-chip__label { color: #F5F1E8; }
.ds-chip--on .ds-chip__hint { color: rgba(245,241,232,0.6); }

.ds-card { position: relative; display: flex; flex-direction: column; text-align: left; background: #EFE9DC; border: 1px solid rgba(17,17,17,0.12); border-radius: 14px; overflow: hidden; cursor: pointer; transition: border-color 240ms cubic-bezier(0.22, 0.61, 0.36, 1), transform 240ms cubic-bezier(0.22, 0.61, 0.36, 1), box-shadow 240ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-card:hover { border-color: rgba(17,17,17,0.22); transform: translateY(-2px); box-shadow: 0 6px 18px -6px rgba(17,17,17,0.18), 0 2px 4px rgba(17,17,17,0.06); }
.ds-card[aria-pressed="true"] { border-color: #111111; box-shadow: 0 0 0 1px #111111, 0 6px 18px -6px rgba(17,17,17,0.18); }
.ds-card__thumb { aspect-ratio: 3 / 2; background: #F5F1E8; border-bottom: 1px solid rgba(17,17,17,0.12); padding: 24px; display: flex; align-items: center; justify-content: center; }
.ds-card__thumb svg { width: 100%; height: 100%; }
.ds-card__body { padding: 16px 24px 24px; display: flex; flex-direction: column; gap: 4px; }
.ds-card__era { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: #A79F93; }
.ds-card__name { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 500; font-size: 22px; line-height: 1.15; letter-spacing: -0.01em; color: #111111; margin-top: 2px; }
.ds-card__rooms { font-family: 'Inter', -apple-system, sans-serif; font-size: 13px; color: #3A352C; }
.ds-card__badge { margin-top: 12px; align-self: flex-start; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; padding: 4px 8px; border-radius: 4px; }
.ds-card__badge--good { background: rgba(124,133,109,0.18); color: #5E6B4C; }
.ds-card__dot { position: absolute; top: 16px; right: 16px; width: 12px; height: 12px; border-radius: 50%; border: 1.5px solid rgba(17,17,17,0.22); background: #F5F1E8; transition: background 240ms cubic-bezier(0.22, 0.61, 0.36, 1), border-color 240ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-card[aria-pressed="true"] .ds-card__dot { background: #D8A24A; border-color: #111111; }

.ds-eyebrow { display: inline-flex; align-items: center; gap: 10px; font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 11px; font-weight: 500; letter-spacing: 0.16em; text-transform: uppercase; color: #A79F93; }
.ds-eyebrow__breath { width: 7px; height: 7px; border-radius: 50%; background: #D8A24A; box-shadow: 0 0 0 4px rgba(216,162,74,0.16); animation: ds-breath 1800ms cubic-bezier(0.22, 0.61, 0.36, 1) infinite; }
@keyframes ds-breath { 0%, 100% { box-shadow: 0 0 0 4px rgba(216,162,74,0.16); } 50% { box-shadow: 0 0 0 9px rgba(216,162,74,0.04); } }
@media (prefers-reduced-motion: reduce) { .ds-eyebrow__breath { animation: none; } }

.ds-readout { display: flex; flex-direction: column; gap: 6px; }
.ds-readout__deg { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 500; font-size: 96px; line-height: 1; letter-spacing: -0.04em; color: #111111; }
.ds-readout__facing { font-family: 'Cormorant Garamond', Georgia, serif; font-style: italic; font-weight: 400; font-size: 28px; color: #D8A24A; }
.ds-readout__hint { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 10px; letter-spacing: 0.16em; text-transform: uppercase; color: #A79F93; margin-top: 8px; }

.ds-slider { display: flex; flex-direction: column; gap: 24px; max-width: 760px; }
.ds-slider__readout { display: flex; align-items: baseline; gap: 24px; }
.ds-slider__pre { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; color: #A79F93; font-weight: 500; }
.ds-slider__big { font-family: 'Cormorant Garamond', Georgia, serif; font-weight: 500; font-size: 96px; line-height: 1; letter-spacing: -0.04em; color: #111111; margin-left: 12px; }
.ds-slider__badge { font-family: 'JetBrains Mono', ui-monospace, monospace; font-size: 11px; letter-spacing: 0.16em; text-transform: uppercase; padding: 5px 10px; border-radius: 4px; color: #6b4d18; background: rgba(216,162,74,0.16); border: 1px solid #D8A24A; }
.ds-slider__track { position: relative; height: 10px; background: #EFE9DC; border: 1px solid rgba(17,17,17,0.12); border-radius: 999px; overflow: hidden; }
.ds-slider__seg { position: absolute; top: 0; bottom: 0; }
.ds-slider__seg--ground { background: #A79F93; opacity: 0.35; }
.ds-slider__seg--transition { background: #7C856D; opacity: 0.25; }
.ds-slider__seg--golden { background: #D8A24A; opacity: 0.4; }
.ds-slider__seg--turbulent { background: #B96F4D; opacity: 0.25; }
.ds-slider__range { position: relative; appearance: none; width: 100%; height: 22px; margin: -16px 0 0 0; background: transparent; cursor: pointer; }
.ds-slider__range::-webkit-slider-thumb { appearance: none; width: 22px; height: 22px; border-radius: 50%; background: #F5F1E8; border: 2px solid #111111; box-shadow: 0 0 0 4px rgba(216,162,74,0.20), 0 1px 2px rgba(17,17,17,0.06); cursor: grab; transition: transform 140ms cubic-bezier(0.22, 0.61, 0.36, 1); }
.ds-slider__range::-webkit-slider-thumb:hover { transform: scale(1.1); }
.ds-slider__range::-moz-range-thumb { width: 22px; height: 22px; border-radius: 50%; background: #F5F1E8; border: 2px solid #111111; box-shadow: 0 0 0 4px rgba(216,162,74,0.20), 0 1px 2px rgba(17,17,17,0.06); cursor: grab; }
